-- Schema v1 of AppDatabase, dumped 2026-11-23 before the change to v2
-- (ADR 0007). Used by the migration test T30.1. Do not edit.
CREATE TABLE "app_meta" ("key" TEXT NOT NULL, "value" TEXT NOT NULL, PRIMARY KEY ("key"));
CREATE TABLE "catalogue_sites" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "region" TEXT NULL, "country_code" TEXT NULL, "lat" REAL NOT NULL, "lon" REAL NOT NULL, "max_depth_m" REAL NULL, "types" TEXT NOT NULL DEFAULT '', PRIMARY KEY ("id"));
CREATE TABLE "dive_computers" ("id" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "vendor" TEXT NOT NULL, "product" TEXT NOT NULL, "model_number" INTEGER NULL, "serial" TEXT NULL, "firmware" TEXT NULL, "address" TEXT NULL, "last_fingerprint" BLOB NULL, PRIMARY KEY ("id"));
CREATE TABLE "dive_events" ("id" TEXT NOT NULL, "dive_id" TEXT NOT NULL REFERENCES dives (id) ON DELETE CASCADE, "time_s" INTEGER NOT NULL, "type" TEXT NOT NULL, "value" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "dive_samples" ("dive_id" TEXT NOT NULL REFERENCES dives (id) ON DELETE CASCADE, "time_s" INTEGER NOT NULL, "depth_m" REAL NOT NULL, "temperature_c" REAL NULL, "heart_rate" INTEGER NULL, "ndl_s" INTEGER NULL, "deco_ceiling_m" REAL NULL, "deco_time_s" INTEGER NULL, "gas_index" INTEGER NULL, PRIMARY KEY ("dive_id", "time_s"));
CREATE TABLE "dive_tank_pressures" ("dive_id" TEXT NOT NULL REFERENCES dives (id) ON DELETE CASCADE, "time_s" INTEGER NOT NULL, "tank_index" INTEGER NOT NULL, "pressure_bar" REAL NOT NULL, PRIMARY KEY ("dive_id", "time_s", "tank_index"));
CREATE TABLE "dive_tanks" ("dive_id" TEXT NOT NULL REFERENCES dives (id) ON DELETE CASCADE, "tank_index" INTEGER NOT NULL, "volume_l" REAL NULL, "start_pressure_bar" REAL NULL, "end_pressure_bar" REAL NULL, "o2" REAL NULL, "he" REAL NULL, PRIMARY KEY ("dive_id", "tank_index"));
CREATE TABLE "divers" ("id" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "name" TEXT NOT NULL, "first_dive_number" INTEGER NOT NULL DEFAULT 1, PRIMARY KEY ("id"));
CREATE TABLE "dives" ("id" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "diver_id" TEXT NOT NULL REFERENCES divers (id), "dive_number" INTEGER NOT NULL, "site_name" TEXT NULL, "site_catalogue_id" TEXT NULL, "site_lat" REAL NULL, "site_lon" REAL NULL, "dive_computer_id" TEXT NULL REFERENCES dive_computers (id), "source" TEXT NOT NULL, "source_id" TEXT NULL, "start_local" INTEGER NOT NULL, "utc_offset_s" INTEGER NULL, "duration_s" INTEGER NOT NULL, "max_depth_m" REAL NOT NULL, "avg_depth_m" REAL NULL, "min_temperature_c" REAL NULL, "max_temperature_c" REAL NULL, "water_type" TEXT NULL, "notes" TEXT NULL, "rating" INTEGER NULL, PRIMARY KEY ("id"));
CREATE INDEX dives_by_diver ON dives (diver_id, start_local);
